// PROBE — the definitive defect cases, written against the FUTURE pure brick
// entry point `resolveBricks` (does not exist yet in game/neon.js).
// Run today: module-level failure => every case red.
import { test } from 'node:test';
import assert from 'node:assert/strict';

import {
  createState,
  step,
  resolveBricks, // <-- does not exist yet
  collides,
  ballSpeed,
  PADDLE_Y,
  BALL_R,
  WIDTH,
} from '../game/neon.js';

test('D1: bottom-face hit bounces the ball out and kills the brick', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // row 0: x 4..76, y 48..68
  const ball = state.ball;
  ball.x = 40;
  ball.y = brick.y + brick.h + BALL_R - 3; // bottom edge 3px inside the bottom face
  ball.vx = 0;
  ball.vy = -ballSpeed(1); // climbing toward the brick
  ball.prevX = ball.x;
  ball.prevY = ball.y + 5; // came from 5px lower
  resolveBricks(state);
  assert.equal(ball.vy, ballSpeed(1), 'vy must flip to DOWN');
  assert.equal(ball.y, brick.y + brick.h + BALL_R, 'ball pushed out to the bottom face');
  assert.equal(brick.alive, false, 'brick broken');
  assert.ok(!collides(ball, brick), 'ball out of the rectangle');
});

test('D2: side hit flips vx only, not vy', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // x 4..76, y 48..68
  const ball = state.ball;
  ball.y = brick.y + brick.h / 2;
  ball.x = brick.x - BALL_R + 2; // right edge 2px inside the left face
  ball.vx = ballSpeed(1) * 0.6;
  ball.vy = 0;
  ball.prevX = ball.x - 5;
  ball.prevY = ball.y;
  resolveBricks(state);
  assert.ok(ball.vx < 0, 'vx must flip to LEFT');
  assert.equal(ball.vy, 0, 'vy untouched');
  assert.equal(ball.x, brick.x - BALL_R, 'pushed out left');
});

test('D2: corner hit flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // x 4..76, y 48..68
  const ball = state.ball;
  const cx = brick.x - BALL_R;
  const cy = brick.y - BALL_R;
  ball.prevX = cx - 10;
  ball.prevY = cy - 10;
  ball.x = cx + 10;
  ball.y = cy + 10;
  ball.vx = 200;
  ball.vy = 200; // perfect diagonal, equal speeds
  resolveBricks(state);
  assert.equal(ball.vx, -200);
  assert.equal(ball.vy, -200);
  assert.equal(ball.x, cx);
  assert.equal(ball.y, cy);
});

test('D3: after resolution the ball is out of the rectangle and is not re-inverted', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // y 48..68
  const ball = state.ball;
  ball.x = 40;
  ball.y = brick.y + brick.h / 2 + 12; // deep inside the brick
  ball.vx = 0;
  ball.vy = -ballSpeed(1);
  ball.prevX = ball.x;
  ball.prevY = ball.y + 13; // came from below
  resolveBricks(state);
  assert.ok(!collides(ball, brick), 'invariant: ball out of the rectangle after resolution');
  assert.equal(ball.vy, ballSpeed(1), 'vy flipped DOWN (exits through the bottom face)');
  step(state, 1 / 60);
  assert.equal(ball.vy, ballSpeed(1), 'no re-inversion one frame later');
});

test('D4: a seam between two bricks bounces once, never cancels to zero', () => {
  const state = createState(1);
  const left = state.bricks[0]; // x 4..76
  const right = state.bricks[1]; // x 84..156
  const ball = state.ball;
  const seamX = left.x + left.w + (right.x - (left.x + left.w)) / 2; // gap center: 80
  ball.x = seamX; // ball spans 73..87: inside BOTH bricks
  ball.y = left.y - BALL_R - 8; // 33 — fully above row 0
  ball.vx = 0;
  ball.vy = ballSpeed(1); // descending straight down the seam
  ball.prevX = ball.x;
  ball.prevY = ball.y - 5;
  resolveBricks(state);
  assert.ok(ball.vy < 0, 'must bounce UP, not fall through the seam');
  assert.equal(ball.y, left.y - BALL_R, 'pushed to just above the row top');
  assert.ok(!collides(ball, left) && !collides(ball, right), 'out of both bricks');
});

test('D5: level 6, dt=50ms — the ball cannot jump through a brick', () => {
  const state = createState(6);
  const brick = state.bricks[0]; // y 48..68
  const ball = state.ball;
  ball.x = 40;
  ball.y = brick.y - BALL_R - 1; // 1px above the brick top
  ball.vx = 0;
  ball.vy = ballSpeed(6); // 710, descending
  step(state, 0.05); // moves 35.5px: lands fully BELOW the brick (top edge 68.5 > 68)
  assert.ok(!collides(ball, brick), 'sanity: a plain overlap test sees nothing');
  resolveBricks(state);
  assert.equal(ball.vy, -ballSpeed(6), 'bounced back up');
  assert.ok(ball.y < brick.y, 'ball is above the brick');
  assert.equal(brick.alive, false, 'brick hit and broken despite the jump');
});

test('D6: level 6, dt=50ms — the ball cannot jump through the paddle', () => {
  const state = createState(6);
  const ball = state.ball;
  ball.x = WIDTH / 2;
  ball.y = PADDLE_Y - BALL_R - 1; // 1px above the paddle top
  ball.vx = 0;
  ball.vy = ballSpeed(6); // 710 descending
  const lost = step(state, 0.05); // jumps 35.5px: bottom edge lands below the paddle
  assert.equal(lost, false, 'must not be lost yet');
  assert.ok(ball.vy < 0, 'must bounce off the paddle');
  assert.equal(ball.y, PADDLE_Y - BALL_R, 'resting on the paddle top');
});

test('D6: grazing the paddle corner still bounces', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x - 3; // center 3px left of the paddle, body overlaps it
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  assert.ok(ball.vy < 0, 'corner graze must bounce');
});

test('D7: a dead-center paddle hit must not produce vx = 0', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x + state.paddle.w / 2; // dead center
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  assert.ok(Math.abs(ball.vx) >= 0.2 * ballSpeed(1), 'horizontal floor must hold');
  assert.ok(ball.vy < 0, 'bounced up');
});

test('D8: a paddle bounce conserves the level speed', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x; // extreme edge: hit = -1
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  const norm = Math.hypot(ball.vx, ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-6, `norm ${norm.toFixed(2)} != speed ${ballSpeed(1)}`);
});

// PROBE (naive) — same cases wired to the NAIVE fix: "flip vy on overlap,
