// --- The naive fix, faithfully copied --------------------------------
function naiveResolveBricks(state) {
  for (const brick of state.bricks) {
    if (!brick.alive) continue;
    if (collides(state.ball, brick)) {
      brick.alive = false;
      state.combo += 1;
      state.score += scoreForBrick(brick, state.combo);
      state.ball.vy = -state.ball.vy; // "the bounce"
    }
  }
}
