  assert.ok(ball.vx < 0, 'vx must flip to LEFT');
  assert.equal(ball.vy, 0, 'vy untouched');
  assert.equal(ball.x, brick.x - BALL_R, 'pushed out left');
});

test('D2: corner hit flips both axes', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // x 4..76, y 48..68
  const ball = state.ball;
  const cx = brick.x - BALL_R;
  const cy = brick.y - BALL_R;
