// D3 — sticking: resolution must push the ball out of the rectangle and never
// re-invert it on the next pass.
test('D3: after resolution the ball is out of the rectangle and is not re-inverted', () => {
  const state = createState(1);
  const brick = state.bricks[0]; // y 48..68
  const ball = state.ball;
  ball.x = 40;
  ball.y = brick.y + brick.h / 2 + 12; // deep inside the brick
  ball.vx = 0;
  ball.vy = -ballSpeed(1);
  ball.prevX = ball.x;
  ball.prevY = ball.y + 13; // came from below
  resolveBricks(state);
  assert.ok(!collides(ball, brick), 'invariant: ball out of the rectangle after resolution');
  assert.equal(ball.vy, ballSpeed(1), 'vy flipped DOWN (exits through the bottom face)');
  step(state, 1 / 60);
  assert.equal(ball.vy, ballSpeed(1), 'no re-inversion one frame later');
});

// D4 — seam ghost collision: two bricks touched in one pass must resolve as
// ONE bounce, never two flips that cancel to zero.
test('D4: a seam between two bricks bounces once, never cancels to zero', () => {
  const state = createState(1);
  const left = state.bricks[0]; // x 4..76
  const right = state.bricks[1]; // x 84..156
  const ball = state.ball;
  const seamX = left.x + left.w + (right.x - (left.x + left.w)) / 2; // gap center: 80
  ball.x = seamX; // ball spans 73..87: inside BOTH bricks
  ball.y = left.y + 6; // 54 — overlapping L and R in the seam band
  ball.vx = 0;
  ball.vy = ballSpeed(1); // descending straight down the seam
  ball.prevX = ball.x;
  ball.prevY = 30; // fully above the row (bottom edge 37 < 41)
  resolveBricks(state);
  assert.ok(ball.vy < 0, 'must bounce UP, not fall through the seam');
  assert.equal(ball.y, left.y - BALL_R, 'pushed to just above the row top');
  assert.ok(!collides(ball, left) && !collides(ball, right), 'out of both bricks');
});

