// D6 — paddle: the discrete band test misses a fast descent (level 6, dt=50ms:
// 35.5 px > 12 + 14) and a corner graze (center-only x test).
test('D6: level 6, dt=50ms — the ball cannot jump through the paddle', () => {
  const state = createState(6);
  const ball = state.ball;
  ball.x = WIDTH / 2;
  ball.y = PADDLE_Y - BALL_R - 1; // 1px above the paddle top
  ball.vx = 0;
  ball.vy = ballSpeed(6); // 710 descending
  const lost = step(state, 0.05); // jumps 35.5px past the paddle
  assert.equal(lost, false, 'must not be lost yet');
  assert.ok(ball.vy < 0, 'must bounce off the paddle');
  assert.equal(ball.y, PADDLE_Y - BALL_R, 'resting on the paddle top');
});

test('D6: grazing the paddle corner still bounces', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x - 3; // center 3px left of the paddle, body overlaps it
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  assert.ok(ball.vy < 0, 'corner graze must bounce');
});

// D7 — dead angle: a dead-center paddle hit must not freeze vx at 0 (the ball
// would loop on the vertical forever).
test('D7: a dead-center paddle hit must not produce vx = 0', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x + state.paddle.w / 2; // dead center
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  assert.ok(Math.abs(ball.vx) >= 0.2 * ballSpeed(1), 'horizontal floor must hold');
  assert.ok(ball.vy < 0, 'bounced up');
});

// D8 — speed: a paddle bounce must conserve the level speed (elastic bounce).
test('D8: a paddle bounce conserves the level speed', () => {
  const state = createState(1);
  const ball = state.ball;
  ball.x = state.paddle.x; // extreme edge: hit = -1
  ball.y = PADDLE_Y - BALL_R - 1;
  ball.vx = 0;
  ball.vy = ballSpeed(1);
  step(state, 1 / 60);
  const norm = Math.hypot(ball.vx, ball.vy);
  assert.ok(Math.abs(norm - ballSpeed(1)) < 1e-6, `norm ${norm.toFixed(2)} != speed ${ballSpeed(1)}`);
});

