edits.newText:
// Paddle. The ball bounces when its body crosses the paddle's top face this
// frame (swept), or when it is already inside the paddle box — e.g. the
// mouse teleported the paddle under it. Either way the ball always exits
// through the top: it is placed on the top face and sent upward.
const overPaddle =
  ball.x >= paddle.x - ball.r && ball.x <= paddle.x + paddle.w + ball.r;
const crossedTop =
  ball.prevY + ball.r <= paddle.y && ball.y + ball.r >= paddle.y;
const insidePaddle =
  ball.y + ball.r >= paddle.y &&
  ball.y - ball.r <= paddle.y + paddle.h;
if (ball.vy > 0 && overPaddle && (crossedTop || insidePaddle)) {
  ball.y = paddle.y - ball.r;
  // The rebound angle depends on where the paddle was hit: -1..1 across the
  // width. A dead-center hit must not freeze vx at 0 (the ball would loop on
  // the vertical), so the horizontal component keeps a floor of 20% of the
  // level speed, and vy is renormalized so the bounce conserves the level
  // speed exactly (elastic bounce).
  const speed = ballSpeed(state.level);
  const hit = Math.max(-1, Math.min(1, (ball.x - (paddle.x + paddle.w / 2)) / (paddle.w / 2)));
  const vxAbs = Math.max(Math.abs(speed * 0.6 * hit), speed * 0.2);
  ball.vx = Math.sign(hit || ball.vx || 1) * vxAbs;
  ball.vy = -Math.sqrt(speed * speed - vxAbs * vxAbs);
  state.combo = 0; // touching the paddle resets the combo
}

