node -e '
import("./game/neon.js").then(({ createState, step, resolveBricks, collides, ballSpeed, WIDTH, PADDLE_Y, BALL_R }) => {
  // Fuzz: high level, big dt — ball must never pass through a live brick
  let state = createState(12);
  const ball = state.ball;
  ball.x = 320; ball.y = 200; ball.vx = 0.6*ballSpeed(12); ball.vy = -ballSpeed(12);
  let passes = 0;
  for (let i = 0; i < 2000; i++) {
    const dt = 0.02 + (i % 3) * 0.015; // 20..50ms frames
    step(state, dt);
    resolveBricks(state);
    // walls
    if (ball.x - ball.r < 0 || ball.x + ball.r > WIDTH || ball.y - ball.r < 0) {}
    for (const b of state.bricks) {
      if (b.alive && collides(ball, b)) {
        console.log("STILL OVERLAPPING a live brick after resolution at iter", i, {x: ball.x, y: ball.y});
        process.exit(1);
      }
    }
    if (state.bricks.every(b => !b.alive)) {
      // level cleared — respawn like the game loop does
      state.level += 1;
